draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw elderly person
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 20, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 40);
  ctx.lineTo(W/2 - 50, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 60);
  ctx.lineTo(W/2 - 70, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 60);
  ctx.lineTo(W/2 - 30, H/2 + 50);
  ctx.stroke();

  // draw dog
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2 + 20, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 40);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 70 + 20 * Math.sin(t), H/2 + 40);
  ctx.stroke();

  // draw leash
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 80);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.restore();
}
